<?php require_once __DIR__.'/includes/permissions.php';require_permission('announcements.manage');$pdo=db();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$a=post('action');$id=(int)post('id',0);if($a==='save'){$data=[trim((string)post('title')),trim((string)post('content')),post('publish_date')?:date('Y-m-d'),post('expiry_date')?:null,post('status','Draft')];if(!$data[0]||!$data[1])throw new Exception('Title and content are required.');if($id)$pdo->prepare('UPDATE public_announcements SET title=?,content=?,publish_date=?,expiry_date=?,status=? WHERE id=?')->execute([...$data,$id]);else{$pdo->prepare('INSERT INTO public_announcements(title,content,publish_date,expiry_date,status,created_by) VALUES(?,?,?,?,?,?)')->execute([...$data,current_user()['id']]);$id=(int)$pdo->lastInsertId();}audit($id?'UPDATE':'CREATE','public_announcements',$id,'Announcement saved');flash('success','Announcement saved.');redirect(BASE_URL.'/announcements.php');}elseif($a==='delete'){$pdo->prepare('UPDATE public_announcements SET status="Archived" WHERE id=?')->execute([$id]);audit('ARCHIVE','public_announcements',$id,'Announcement archived');flash('success','Announcement archived.');redirect(BASE_URL.'/announcements.php');}}catch(Throwable $e){$error=$e->getMessage();}}$rows=$pdo->query('SELECT * FROM public_announcements ORDER BY publish_date DESC,created_at DESC')->fetchAll();include __DIR__.'/includes/header.php';?><div class="page-head"><div><h1>Announcements</h1><p>Publish health information to the public portal.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="panel mb-4"><div class="panel-head"><h5>Create Announcement</h5></div><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="save"><div class="col-md-5"><label>Title *</label><input name="title" class="form-control" required></div><div class="col-md-2"><label>Publish Date</label><input type="date" name="publish_date" value="<?=date('Y-m-d')?>" class="form-control"></div><div class="col-md-2"><label>Expiry</label><input type="date" name="expiry_date" class="form-control"></div><div class="col-md-3"><label>Status</label><select name="status" class="form-select"><option>Draft</option><option>Published</option><option>Archived</option></select></div><div class="col-12"><label>Content *</label><textarea name="content" rows="4" class="form-control" required></textarea></div><div class="col-12"><button class="btn btn-primary">Save Announcement</button></div></form></div><div class="panel"><div class="panel-head"><h5>Announcements</h5></div><div class="table-responsive"><table class="table"><thead><tr><th>Title</th><th>Publish</th><th>Expiry</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['publish_date'])?></td><td><?=e($r['expiry_date']??'—')?></td><td><?=e($r['status'])?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-secondary">Archive</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/includes/footer.php'; ?>
